function parseDiscoveryJson(v){
 const raw=String(v||'').trim().replace(/^```(?:json)?/i,'').replace(/```$/,'').trim();
 const first=raw.indexOf('{');if(first<0)throw new Error('AI response did not contain a JSON object');
 let depth=0,inString=false,escaped=false,last=-1;
 for(let i=first;i<raw.length;i++){const ch=raw[i];if(inString){if(escaped)escaped=false;else if(ch==='\\')escaped=true;else if(ch==='"')inString=false;continue;}if(ch==='"'){inString=true;continue;}if(ch==='{')depth++;else if(ch==='}'&&--depth===0){last=i;break;}}
 if(last<0)throw new Error('AI returned incomplete JSON');
 const candidate=raw.slice(first,last+1);
 try{return JSON.parse(candidate);}catch(firstError){
  const repaired=candidate.replace(/,\s*([}\]])/g,'$1').replace(/([{,]\s*)([A-Za-z_][\w-]*)(\s*:)/g,'$1"$2"$3');
  try{return JSON.parse(repaired);}catch(_){throw firstError;}
 }
}
async function discoverSearch(q){
 const response=await fetch(API+'/webSearch?q='+encodeURIComponent(q)+'&max=5',{headers:{accept:'application/json'}});
 const raw=await response.text();let data;try{data=JSON.parse(raw);}catch(_){throw new Error('Search service returned an unreadable response');}
 if(!response.ok||!data.available)throw new Error(data.error||'Web search temporarily unavailable');
 return Array.isArray(data.results)?data.results:[];
}
function normaliseDiscoverySources(rows){
 return [...new Map((rows||[]).filter(x=>x&&x.url&&x.title).map(x=>{let url;try{url=new URL(String(x.url));if(!['http:','https:'].includes(url.protocol))return null;}catch(_){return null;}return [url.href,{title:String(x.title).trim(),url:url.href,snippet:String(x.snippet||x.description||'').trim()}];}).filter(Boolean)).values()];
}
function fallbackDiscoveryLeads(sources,category,industry,count){
 return sources.slice(0,count).map((s,i)=>({organisation:s.title||'Organisation from public search result',category,industry,city:'',country:'',website:'',contactEmail:'',summary:s.snippet||'Public search result identified for further research. Open the source to verify the organisation and its current activities.',fitReason:'Potential relevance to '+industry+'; this is an initial research match, not verified buying intent or a confirmed technology gap.',approach:'Review the source and organisation website, identify the appropriate decision-maker, then send a tailored introduction focused on the organisation’s industry workflow.',priorityScore:Math.max(35,65-i*3),sources:[s],researchStatus:'Needs verification'}));
}
