function renderDiscovered(){const el=$('discoveredLeadResults');if(!el)return;el.innerHTML=discoveredLeads.length?discoveredLeads.map((x,i)=>'<article class="discovered-card"><div class="discovered-card-head"><div><h3>'+esc(x.organisation)+'</h3><div class="meta">'+esc([x.industry,x.city,x.country,x.category,x.researchStatus].filter(Boolean).join(' · '))+'</div></div><div class="fit-score">'+esc(x.priorityScore||50)+' / 100</div></div><p>'+esc(x.summary||'')+'</p><p><b>Why VIORA may fit:</b> '+esc(x.fitReason||'Potential fit to validate.')+'</p><div class="card-actions"><button class="btn" data-discover-detail="'+i+'"><i class="fa-solid fa-chart-pie"></i> Lead intelligence</button><button class="btn" data-discover-save="'+i+'">Add to CRM</button><button class="btn primary" data-discover-draft="'+i+'">Prepare email draft</button></div></article>').join(''):'<div class="empty">No public-source results were returned this time. Try a broader industry or region, or retry when the search connection is available.</div>';}
async function discoverGlobalLeads(){
 const category=$('discoverCategory').value,industry=$('discoverIndustry').value.trim(),region=$('discoverRegion').value,count=Math.max(1,Math.min(10,Number($('discoverCount').value)||5)),detail=$('discoverDetail').value.trim();
 if(!industry){status('discoverStatus','Enter an industry or business type.',true);return;}
 try{
  busy('discoverLeadsBtn',true,'Researching…');status('discoverStatus','Searching multiple public-source routes…');$('discoveredLeadResults').innerHTML='<div class="empty">Searching company sites, directories, trade associations and business networks…</div>';discoveredLeads=[];
  const queries=[
   industry+' companies organisations '+region+' official website',
   industry+' associations chambers business networks '+region,
   industry+' digital transformation ERP CRM POS companies '+region,
   industry+' business directory companies '+region,
   industry+' trade federation members '+region
  ];
  let settled=await Promise.all(queries.map(async q=>{try{return await discoverSearch(q);}catch(_){return [];}}));
  let sources=normaliseDiscoverySources(settled.flat());
  if(sources.length<Math.min(3,count)){
   status('discoverStatus','Broadening the search to find more public listings…');
   const broader=[industry+' leading companies directory',industry+' international association members','global '+industry+' companies official websites'];
   const extra=await Promise.all(broader.map(async q=>{try{return await discoverSearch(q);}catch(_){return [];}}));
   sources=normaliseDiscoverySources([...sources,...extra.flat()]);
  }
  if(!sources.length)throw new Error('The live search service did not return any public sources. Check the web-search connection and retry; no organisations will be invented.');
  const limited=sources.slice(0,Math.max(count,Math.min(20,count*2)));
  status('discoverStatus','Found '+sources.length+' public sources. Building prospect matches…');
  const fallback=fallbackDiscoveryLeads(limited,category,industry,count);
  // Publish evidence-backed results immediately. AI enrichment is optional and
  // must never make the discovery screen fail when its output is malformed.
  discoveredLeads=fallback;renderDiscovered();
  status('discoverStatus',sources.length+' public sources found. AI is adding fit analysis where available…');
  const prompt='Return one valid JSON object only, with no markdown: {"leads":[{"organisation":"","category":"Business|Investor|Partner|Industry","industry":"","city":"","country":"","website":"","contactName":"","contactEmail":"","phone":"","summary":"","fitReason":"","approach":"","opportunityAreas":[""],"observedSignals":[""],"recommendedEntryPoint":"","confidence":0,"priorityScore":0,"sources":[{"title":"","url":""}]}]}. Scope: '+JSON.stringify({category,industry,region,detail,count})+'. Use only supplied evidence. Never invent facts, people, emails, locations, software or buying intent. Email only when exact email appears in a supplied snippet. URLs must exactly match supplied URLs. Treat fit as a hypothesis. Return up to '+count+' results. Evidence: '+JSON.stringify(limited);
  try{
   const a=await api('/outreach/draft',{system:'You are a factual global B2B prospect researcher for VIORA Ecosystems. Return syntactically valid JSON only. Do not hallucinate.',message:prompt});
   const parsed=parseDiscoveryJson(a.reply||a.response||a.text||a.content||'');
   const allowed=new Set(limited.map(s=>s.url));
   const enriched=(Array.isArray(parsed.leads)?parsed.leads:[]).map(x=>{
    const ss=(Array.isArray(x.sources)?x.sources:[]).filter(s=>allowed.has(s.url));
    const em=String(x.contactEmail||'').trim(),phone=String(x.phone||'').trim(),person=String(x.contactName||'').trim();
    const evidence=limited.map(s=>s.title+' '+s.snippet).join(' ');
    return {...x,organisation:String(x.organisation||'').trim(),category:['Business','Investor','Partner','Industry'].includes(x.category)?x.category:category,industry:x.industry||industry,contactName:person&&evidence.includes(person)?person:'',contactEmail:em&&evidence.includes(em)?em:'',phone:phone&&evidence.includes(phone)?phone:'',website:allowed.has(x.website)?x.website:'',opportunityAreas:Array.isArray(x.opportunityAreas)?x.opportunityAreas.filter(v=>typeof v==='string').slice(0,5):[],observedSignals:Array.isArray(x.observedSignals)?x.observedSignals.filter(v=>typeof v==='string').slice(0,5):[],recommendedEntryPoint:String(x.recommendedEntryPoint||''),confidence:Math.max(0,Math.min(100,Number(x.confidence)||0)),priorityScore:Math.max(1,Math.min(100,Number(x.priorityScore)||50)),sources:ss,researchStatus:'AI analysed · verify before contact'};
   }).filter(x=>x.organisation&&x.sources.length).slice(0,count);
   if(enriched.length)discoveredLeads=enriched;
   renderDiscovered();
   status('discoverStatus',discoveredLeads.length+' prospects ready from '+sources.length+' public sources. '+(enriched.length?'AI fit analysis added.':'Using evidence-backed source matches because AI returned no valid structured prospects.')+' Verify before outreach.');
  }catch(aiError){
   renderDiscovered();
   status('discoverStatus',discoveredLeads.length+' evidence-backed prospects ready. AI enrichment was unavailable or malformed, so the discovery results were kept instead of failing. You can still save prospects and prepare drafts.');
  }
 }catch(e){
  discoveredLeads=[];renderDiscovered();status('discoverStatus','Discovery could not retrieve live public results: '+e.message,true);
 }finally{busy('discoverLeadsBtn',false);}
}
