async function sendEmail(e){
 e?.preventDefault();
 const subject=$('mailSubject').value.trim(),textBody=$('mailBody').value.trim(),chosen=selectedMailLeads(),manual=parseManualMailRecipients();
 if(!subject||!textBody){status('mailStatus','Subject and message are required.',true);return;}
 const blocked=chosen.filter(l=>String(l.status||'').toLowerCase()==='do not contact');
 if(blocked.length){status('mailStatus','Remove Do not contact prospects before sending: '+blocked.map(l=>l.company||l.fullName||l.email).join(', '),true);return;}
 const recipients=[],seen=new Set();
 for(const lead of chosen){const to=String(lead.email||'').trim(),key=to.toLowerCase();if(!to||seen.has(key))continue;seen.add(key);recipients.push({to,lead});}
 for(const to of manual){if(seen.has(to))continue;seen.add(to);recipients.push({to,lead:leadList().find(l=>(l.email||'').trim().toLowerCase()===to)||null});}
 if(!recipients.length){status('mailStatus','Select at least one saved lead or enter one or more email addresses.',true);return;}
 const blockedManual=recipients.filter(x=>x.lead&&String(x.lead.status||'').toLowerCase()==='do not contact');
 if(blockedManual.length){status('mailStatus','These recipients are marked Do not contact: '+blockedManual.map(x=>x.to).join(', '),true);return;}
 const invalid=recipients.filter(x=>!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(x.to));
 if(invalid.length){status('mailStatus','Check these email addresses: '+invalid.map(x=>x.to).join(', '),true);return;}
 const ok=await showConfirm('Confirm multi-recipient send','Send “'+subject+'” as '+recipients.length+' separate email'+(recipients.length===1?'':'s')+'? Each recipient will receive only their own message, and every send will be logged in Outreach and the main VIORA Communications log.','Send '+recipients.length+' email'+(recipients.length===1?'':'s'));
 if(!ok)return;
 let sent=0,failed=0;const failures=[],successAddresses=[];
 try{
  busy('sendBtn',true,'Sending 0/'+recipients.length+'…');
  for(let i=0;i<recipients.length;i++){
   const {to,lead}=recipients[i],id=push(ref(db,ROOT+'/emails')).key,commLogId=push(ref(db,ORG+'/commLog')).key,now=stamp();
   const audit={id,to,subject,text:textBody,company:lead?.company||lead?.fullName||'',leadId:lead?.id||null,commLogId,direction:'outbound',status:'queued',providerId:null,timestamp:now,sentBy:currentUser.uid,sentByEmail:currentUser.email,approvedAt:now,source:'Outreach Centre',batchSize:recipients.length};
   const comm={id:commLogId,channel:'em',recipientId:lead?.id||to,recipientName:lead?.company||lead?.fullName||to,recipientContact:to,subject,message:textBody,sentBy:currentUser.email||currentUser.uid,status:'queued',timestamp:now,leadId:lead?.id||null,outreachEmailId:id,source:'Outreach Centre',batchSize:recipients.length};
   try{
    await set(ref(db,ROOT+'/emails/'+id),audit);
    await set(ref(db,ORG+'/commLog/'+commLogId),comm);
    await update(ref(db,ROOT+'/emails/'+id),{status:'sending',attemptedAt:stamp()});
    await update(ref(db,ORG+'/commLog/'+commLogId),{status:'sending',attemptedAt:stamp()});
    const result=await api('/sendEmail',{to,subject,text:textBody,replyTo:'support@viora.co.ke'});
    const sentAt=stamp();
    await update(ref(db,ROOT+'/emails/'+id),{status:'sent',providerId:result.id||null,sentAt});
    await update(ref(db,ORG+'/commLog/'+commLogId),{status:'sent',providerId:result.id||null,sentAt});
    if(lead?.id)await update(ref(db,ORG+'/leads/'+lead.id),{status:lead.status==='New'?'Contacted':lead.status,lastContactedAt:sentAt,updatedAt:sentAt});
    sent++;successAddresses.push(to.toLowerCase());
   }catch(err){
    failed++;failures.push(to);
    const failedAt=stamp();
    await update(ref(db,ROOT+'/emails/'+id),{status:'failed',error:err.message,failedAt}).catch(()=>{});
    await update(ref(db,ORG+'/commLog/'+commLogId),{status:'failed',error:err.message,failedAt}).catch(()=>{});
   }
   busy('sendBtn',true,'Sending '+(i+1)+'/'+recipients.length+'…');
   status('mailStatus','Processed '+(i+1)+' of '+recipients.length+' · '+sent+' accepted · '+failed+' failed'+(failures.length?' · '+failures.join(', '):''));
  }
  if(successAddresses.length){
   const sentSet=new Set(successAddresses);
   $('mailLeadList').querySelectorAll('input[name="mailLeadChoice"]').forEach(box=>{const lead=leads[box.value];if(lead&&sentSet.has(String(lead.email||'').trim().toLowerCase()))box.checked=false;});
   $('mailTo').value=parseManualMailRecipients().filter(address=>!sentSet.has(address)).join(', ');
   updateMailRecipientSummary();
  }
  if(!failed){$('mailBody').value='';closeModal('emailModal');toast(sent+' separate email'+(sent===1?'':'s')+' accepted by the configured provider and recorded. Delivery confirmation depends on webhook tracking.');}
  else{status('mailStatus',sent+' accepted; '+failed+' failed. Only failed recipients remain selected so you can retry safely.',true);}
 }finally{busy('sendBtn',false);renderEmails();renderAnalytics();renderOverview();}
}
function csvEscape(v){return '"'+String(v??'').replace(/"/g,'""')+'"';}
function downloadCsv(name,rows){const csv=rows.map(r=>r.map(csvEscape).join(',')).join('\r\n'),blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}
function exportLeads(){downloadCsv('viora-outreach-leads.csv',[['Organisation','Contact','Email','Phone','Category','City','Country','Status','Follow-up','Website','Notes'],...leadList().map(l=>[l.company,l.contact,l.email,l.phone,l.category,l.city,l.country,l.status,l.followUp,l.website,l.notes])]);}
function exportEmails(){downloadCsv('viora-outreach-communication-ledger.csv',[['Timestamp','Direction','Recipient','Subject','Status','Provider ID','Recorded By','Message'],...emailList().map(e=>[e.timestamp,e.direction,e.to,e.subject,e.status,e.providerId,e.sentByEmail,e.text])]);}

const CITY_CACHE_KEY='viora-city-geocode-cache-v2';
function readCityCache(){try{return JSON.parse(localStorage.getItem(CITY_CACHE_KEY)||'{}')}catch{return {}}}
function writeCityCache(cache){try{localStorage.setItem(CITY_CACHE_KEY,JSON.stringify(cache))}catch{}}
const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
function cityKey(l){return [String(l.address||'').trim(),String(l.city||'').trim(),String(l.country||'').trim()].filter(Boolean).join(', ');}
async function geocodeCity(location,cache){
 if(cache[location])return cache[location];
 const url='https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&q='+encodeURIComponent(location);
 const response=await fetch(url,{headers:{'Accept':'application/json'}});
 if(!response.ok)throw new Error('Geocoder returned '+response.status);
 const results=await response.json();
 const point=results?.[0]?{lat:Number(results[0].lat),lng:Number(results[0].lon)}:null;
 cache[location]=point;writeCityCache(cache);return point;
}
function addVioraMapLayerControl(map,layers){
 const control=L.control({position:'topright'});
 control.onAdd=function(){const root=L.DomUtil.create('div','viora-map-layer-control leaflet-bar');const trigger=L.DomUtil.create('button','viora-map-layer-trigger',root);trigger.type='button';trigger.title='Map layers';trigger.setAttribute('aria-label','Choose map style');trigger.setAttribute('aria-expanded','false');trigger.innerHTML='<i class="fa-solid fa-layer-group"></i>';const menu=L.DomUtil.create('div','viora-map-layer-menu',root);menu.hidden=true;[['vegetation','Vegetation'],['streets','Street map'],['satellite','Satellite'],['osm','OpenStreetMap']].forEach(([key,label])=>{const b=L.DomUtil.create('button','viora-map-layer-option',menu);b.type='button';b.textContent=label;b.setAttribute('aria-pressed',String(key==='vegetation'));b.addEventListener('click',()=>{Object.values(layers).forEach(layer=>{if(map.hasLayer(layer))map.removeLayer(layer)});layers[key].addTo(map);menu.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));menu.hidden=true;trigger.setAttribute('aria-expanded','false');});});trigger.addEventListener('click',()=>{menu.hidden=!menu.hidden;trigger.setAttribute('aria-expanded',String(!menu.hidden));});L.DomEvent.disableClickPropagation(root);L.DomEvent.disableScrollPropagation(root);return root;};control.addTo(map);return control;
}
function ensureWorldMap(){
 if(worldMap||!window.L||!$('worldLeadMap'))return;
 worldMap=L.map('worldLeadMap',{worldCopyJump:true,scrollWheelZoom:true,preferCanvas:true,maxZoom:19}).setView([20,5],1);
 const streets=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'});
 const osmStreets=L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png',{maxZoom:19,subdomains:'abcd',attribution:'© OpenStreetMap contributors © CARTO'});
 const terrain=L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager_nolabels/{z}/{x}/{y}{r}.png',{maxZoom:19,subdomains:'abcd',attribution:'© OpenStreetMap contributors © CARTO'});
 const satellite=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:19,attribution:'Tiles &copy; Esri'});
 const boundaries=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}',{maxZoom:19,opacity:.95,attribution:'Country boundaries & place labels © Esri'});
 // Vegetation/topographic view is the default; country boundaries remain visible on every base layer.
 terrain.addTo(worldMap);boundaries.addTo(worldMap);addVioraMapLayerControl(worldMap,{vegetation:terrain,streets:streets,satellite:satellite,osm:osmStreets});worldMarkers=L.layerGroup().addTo(worldMap);worldMap.fitBounds([[-82,-180],[82,180]],{padding:[8,8],maxZoom:2,animate:false});worldMap._vioraWorldFitted=true;worldMap._vioraUserZoomed=false;worldMap.on('zoomend',()=>{if(worldMap.getZoom()>2)worldMap._vioraUserZoomed=true;});worldMap.on('resize',()=>{worldMap.invalidateSize(true);if(!worldMap._vioraUserZoomed)worldMap.fitBounds([[-82,-180],[82,180]],{padding:[8,8],maxZoom:2,animate:false});});
}
async function renderWorldLeadMap(force=false){
 const token=++mapRenderToken,all=leadList(),located=all.filter(l=>String(l.city||'').trim()&&String(l.country||'').trim()),missing=all.length-located.length;
 $('mapLeadCount').textContent=all.length;$('mapUnmappedCount').textContent=missing;
 if(!window.L){$('worldLeadMap').innerHTML='<div class="map-loading">Map library unavailable. Check the network and refresh.</div>';return;}
 ensureWorldMap();if(!worldMap)return;
 if(!all.length){$('mapCityCount').textContent='0';worldMarkers.clearLayers();if(worldHeat)worldMap.removeLayer(worldHeat);$('worldLeadMap').classList.add('map-empty');return;}
 $('worldLeadMap').classList.remove('map-empty');
 const grouped=new Map();located.forEach(l=>{const key=cityKey(l);if(!grouped.has(key))grouped.set(key,[]);grouped.get(key).push(l)});
 const cache=readCityCache(),points=[];
 let completed=0;
 for(const [location,records] of grouped){
  if(token!==mapRenderToken)return;
  try{
   const p=await geocodeCity(location,cache);
   if(p&&Number.isFinite(p.lat)&&Number.isFinite(p.lng))points.push({location,records,...p});
  }catch(err){console.warn('[VIORA map] Could not resolve city:',location,err);}
  completed++;
  if(completed<grouped.size)await wait(1100);
 }
 if(token!==mapRenderToken)return;
 worldMarkers.clearLayers();if(worldHeat){worldMap.removeLayer(worldHeat);worldHeat=null;}
 const heat=[];
 points.forEach(p=>{
  const count=p.records.length,precise=p.records.some(l=>String(l.address||'').trim()),marker=L.circleMarker([p.lat,p.lng],{radius:Math.min(17,7+Math.sqrt(count)*2),color:'#e0f2fe',weight:2,fillColor:'#38bdf8',fillOpacity:.96});
  const items=p.records.slice(0,18).map(l=>'<div class="map-popup-lead"><b>'+esc(l.company||l.fullName||'Unnamed lead')+'</b><span>'+esc(l.category||'Lead')+' · '+esc(l.source||'VIORA CRM')+'</span></div>').join('');
  marker.bindPopup('<div class="map-popup"><strong>'+esc(p.location)+'</strong><span class="map-popup-count">'+count+' lead'+(count===1?'':'s')+'</span>'+items+(p.records.length>18?'<small>+'+(p.records.length-18)+' more leads</small>':'')+'</div>');
  marker.addTo(worldMarkers);heat.push([p.lat,p.lng,Math.min(1,.35+count*.12)]);
 });
 if(window.L.heatLayer&&heat.length)worldHeat=L.heatLayer(heat,{radius:42,blur:30,maxZoom:6,minOpacity:.32,gradient:{0.12:'#2563eb',0.34:'#06b6d4',0.58:'#22c55e',0.8:'#f59e0b',1:'#ef4444'}}).addTo(worldMap);
 $('mapCityCount').textContent=points.length;
 // Keep the complete world in view; users can zoom to individual city clusters manually.
 if(!worldMap._vioraWorldFitted){worldMap.fitBounds([[-82,-180],[82,180]],{padding:[8,8],maxZoom:2,animate:false});worldMap._vioraWorldFitted=true;}
 if(!points.length&&located.length)$('worldLeadMap').insertAdjacentHTML('beforeend','<div class="map-geocode-note">City names could not be resolved. Check spelling and country values.</div>');
}

