$('modalAiDraft').onclick=modalDraft;$('aiGenerate').onclick=studioDraft;$('aiUse').onclick=()=>{const id=$('aiLeadSelect').value;if(!id||!leads[id]){status('aiStatus','Choose a saved prospect first.',true);return;}openEmailModal(id);$('mailSubject').value=$('aiSubject').value;$('mailBody').value=$('aiBody').value;};
$('aiCopy').onclick=async()=>{try{await navigator.clipboard.writeText(($('aiSubject').value?'Subject: '+$('aiSubject').value+'\n\n':'')+$('aiBody').value);toast('Draft copied to clipboard.');}catch{toast('Clipboard access is unavailable in this browser.',true);}};
$('leadRows').addEventListener('click',e=>{const del=e.target.closest('[data-delete]');if(del){deleteLead(del.dataset.delete);return;}const b=e.target.closest('[data-edit]');if(b)editLead(b.dataset.edit);});
['investorRows','businessRows','industryRows','followupRows'].forEach(id=>$(id).addEventListener('click',e=>{const del=e.target.closest('[data-delete]');if(del){deleteLead(del.dataset.delete);return;}const b=e.target.closest('[data-edit]');if(b)editLead(b.dataset.edit);}));
['emailRows','auditRows'].forEach(id=>$(id).addEventListener('click',e=>{const b=e.target.closest('[data-view-email]');if(b)showEmailDetail(b.dataset.viewEmail);}));
$('leadSearch').addEventListener('input',renderLeadTables);$('leadFilter').addEventListener('change',renderLeadTables);$('emailSearch').addEventListener('input',renderEmails);$('emailStatusFilter').addEventListener('change',renderEmails);$('auditSearch').addEventListener('input',renderAudit);
document.querySelectorAll('[data-category-search]').forEach(el=>el.addEventListener('input',renderLeadTables));
$('leadExport').onclick=exportLeads;$('auditExport').onclick=exportEmails;$('worldMapRefresh')?.addEventListener('click',()=>{try{localStorage.removeItem('viora-city-geocode-cache');}catch(_){}renderWorldLeadMap(true);});$('analyticsRefresh').onclick=renderAnalytics;$('analyticsRange').onchange=renderAnalytics;
$('refreshBtn').onclick=()=>{renderLeadTables();renderFollowups();renderEmails();renderAudit();renderAnalytics();toast('Views refreshed from the latest subscribed records.');};
$('logoutBtn').onclick=()=>signOut(auth);$('mobileMapShortcut')?.addEventListener('click',()=>{showView('businesses');setTimeout(()=>{$('worldLeadMap')?.scrollIntoView({behavior:'smooth',block:'center'});worldMap?.invalidateSize(true);},120);});$('mobileMoreBtn')?.addEventListener('click',()=>{const side=$('sideNav').closest('.sidebar'),open=side.classList.toggle('mobile-open');$('mobileMoreBtn').setAttribute('aria-expanded',String(open));$('mobileNavBackdrop').classList.toggle('is-visible',open);});$('mobileNavBackdrop')?.addEventListener('click',()=>{$('sideNav').closest('.sidebar').classList.remove('mobile-open');$('mobileMoreBtn')?.setAttribute('aria-expanded','false');$('mobileNavBackdrop').classList.remove('is-visible');});document.querySelectorAll('#sideNav .nav-item[data-view]').forEach(b=>b.addEventListener('click',()=>{if(innerWidth<=760){$('sideNav').closest('.sidebar').classList.remove('mobile-open');$('mobileNavBackdrop').classList.remove('is-visible');$('mobileMoreBtn')?.setAttribute('aria-expanded','false');}}));$('mobileMapShortcut')?.addEventListener('click',()=>{$('sideNav').closest('.sidebar').classList.remove('mobile-open');$('mobileNavBackdrop').classList.remove('is-visible');$('mobileMoreBtn')?.setAttribute('aria-expanded','false');});
$('themeBtn').onclick=()=>{const t=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=t;localStorage.setItem('viora-outreach-theme',t);renderAnalytics();renderOverview();};
document.documentElement.dataset.theme=localStorage.getItem('viora-outreach-theme')||'dark';
window.addEventListener('beforeunload',()=>{stopLeads?.();stopEmails?.();stopSuggestions?.();Object.values(charts).forEach(c=>c.destroy());});
